import{_ as n,a0 as d,w as p,s as h,ao as o,I as l,x as e,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Bash 环境变量的那些事 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 环境变量的那些事 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 环境变量的那些事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 环境变量的那些事 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181205 Bash Variables- Environmental and Otherwise","title":"Bash 环境变量的那些事","tag":"201812","desc":""},"relativePath":"201812/20181205 Bash Variables- Environmental and Otherwise.md","filePath":"[post].md"}'),r={name:"201812/20181205 Bash Variables- Environmental and Otherwise.md"};function g(b,s,c,k,u,f){const i=d("Link");return p(),h("div",null,[s[31]||(s[31]=o(`<h1 id="bash-环境变量的那些事" tabindex="-1">Bash 环境变量的那些事 <a class="header-anchor" href="#bash-环境变量的那些事" aria-label="Permalink to “Bash 环境变量的那些事”">​</a></h1><blockquote><p>初学者可以在此教程中了解环境变量。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/wynand-van-poortvliet-40467-unsplash.jpg?itok=tr6Eb4N0" alt=""></p><p>bash 变量，尤其是讨厌的<em>环境变量</em>，已经是一个老生常谈的话题了。我们也更应该对它有一个详细的了解，让它为我们所用。</p><p>下面就打开终端，开始吧。</p><h3 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to “环境变量”">​</a></h3><p><code>HOME</code> （LCTT 译注：双关语）除了是你脱下帽子惬意休息的地方，同时也是 Linux 中的一个变量，它是当前用户主目录的路径：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $HOME</span></span></code></pre></div><p>以上这个命令会显示当前用户的主目录路径，通常都在 <code>/home/&lt;your username&gt;</code> 下。</p><p>顾名思义，变量的值是可以根据上下文变化的。实际上，Linux 系统中每一个用户的 <code>HOME</code> 变量都是不一样的，当然你也可以这样自行更改 <code>HOME</code> 变量的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HOME=/home/&lt;your username&gt;/Documents</span></span></code></pre></div><p>以上这个命令将会把 <code>HOME</code> 变量设置为你的 <code>Documents</code> 目录。</p><p>其中有三点需要留意：</p><ol><li><code>=</code> 符号和其两侧的内容之间不加空格。空格在 shell 中有专门的意义，不能随意地在任何地方添加空格。</li><li>如果你需要对变量进行赋值，只需要使用变量名称就可以了。但如果需要读取或者使用变量的值，需要在变量前面加上一个 <code>$</code> 号。</li><li>更改 <code>HOME</code> 变量具有一定的风险。有很多程序是依赖于 <code>HOME</code> 变量的，更改 <code>HOME</code> 变量可能会导致一些不可预见的结果。例如，如果按照上面的方式更改了 <code>HOME</code> 变量，然后执行不带有任何参数的 <code>cd</code> 命令，在通常情况下，会跳转到用户的主目录下，但在这个时候，会跳转到 <code>HOME</code> 变量指定的目录下。</li></ol><p>上面第 3 点中环境变量的更改并不是持久有效的，在终端关闭后重新打开终端，又或者是新建一个终端，执行 <code>echo $HOME</code> 命令输出的仍然会是初始的值，而不是重新自定义的值。</p><p>在讨论如何持久地更改一个环境变量之前，我们先来看一下另一个比较重要的环境变量。</p><h3 id="path-变量" tabindex="-1">PATH 变量 <a class="header-anchor" href="#path-变量" aria-label="Permalink to “PATH 变量”">​</a></h3><p>在 <code>PATH</code> 变量中存放了一系列目录，而且是放置了可执行程序的目录。正是由于 <code>PATH</code> 变量的存在，让你不需要知道应用程序具体安装到了什么目录，而 shell 却可以正确地找到这些应用程序。</p><p>如果你查看 <code>PATH</code> 变量的值，大概会是以下这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $PATH</span></span>
<span class="line"><span>/usr/local/sbin:/usr/local/bin:/usr/bin:/usr/sbin:/bin:/sbin</span></span></code></pre></div><p>每两个目录之间使用冒号 <code>:</code> 分隔。如果某个应用程序的所在目录不在 <code>PATH</code> 变量中，那么运行的时候就需要声明应用程序的目录让 shell 能够找到。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/home/&lt;user name&gt;/bin/my_program.sh</span></span></code></pre></div><p>例如以上命令就会执行当前用户 <code>bin/</code> 目录下的 <code>my_program.sh</code> 文件。</p><p>有一个常见的问题：如果你不希望弄乱系统的 <code>bin/</code> 目录，同时也不希望你自己的文件被其它人运行，还不想每次运行的时候都要输入完整的路径，那么，你可以在你的主目录中创建一个独立的 <code>bin/</code> 目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir $HOME/bin</span></span></code></pre></div><p>然后将这个目录添加到 <code>PATH</code> 变量中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PATH=$PATH:$HOME/bin</span></span></code></pre></div><p>然后 <code>/home/&lt;user name&gt;/bin/</code> 目录就会出现在 <code>PATH</code> 变量中了。但正如之前所说，这个变更只会在当前的 shell 生效，当前的 shell 一旦关闭，环境变量的值就又恢复原状了。</p><p>如果要让变更对当前用户持续生效，就不能在 shell 中直接执行对应的变更，而是应该将这些变更操作写在每次启动 shell 时都会运行的文件当中。这个文件就是当前用户主目录中的 <code>.bashrc</code> 文件。文件名前面的点号表明这是一个隐藏文件，执行普通的 <code>ls</code> 命令是不会将这个文件显示出来的，但只要在 <code>ls</code> 命令中加入 <code>-a</code> 参数就可以看到这个文件了。</p>`,29)),l("p",null,[s[4]||(s[4]=e("你可以使用诸如 ",-1)),a(i,{href:"https://www.kde.org/applications/utilities/kate/"},{default:t(()=>[...s[0]||(s[0]=[e("kate",-1)])]),_:1}),s[5]||(s[5]=e("、",-1)),a(i,{href:"https://help.gnome.org/users/gedit/stable/"},{default:t(()=>[...s[1]||(s[1]=[e("gedit",-1)])]),_:1}),s[6]||(s[6]=e("、",-1)),a(i,{href:"https://www.nano-editor.org/"},{default:t(()=>[...s[2]||(s[2]=[e("nano",-1)])]),_:1}),s[7]||(s[7]=e(" 或者 ",-1)),a(i,{href:"https://www.vim.org/"},{default:t(()=>[...s[3]||(s[3]=[e("vim",-1)])]),_:1}),s[8]||(s[8]=e(" 这些文本编辑器来打开 ",-1)),s[9]||(s[9]=l("code",null,".bashrc",-1)),s[10]||(s[10]=e(" 文件（但不要用 LibreOffice Writer，它是一个文字处理软件，跟前面几个文字编辑器完全不同）。打开 ",-1)),s[11]||(s[11]=l("code",null,".bashrc",-1)),s[12]||(s[12]=e(" 文件之后，你会看见里面放置了一些 shell 命令，是用于为当前用户设置环境的。",-1))]),s[32]||(s[32]=o('<p>在文件的末尾添加新行并输入以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export PATH=$PATH:$HOME/bin</span></span></code></pre></div><p>保存并关闭 <code>.bashrc</code> 文件，接下来你就会看到 <code>export</code> 语句的效果。执行以下的命令让刚才的修改立即生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>source .bashrc</span></span></code></pre></div><p>刚才执行的 <code>source</code> 命令让 <code>.bashrc</code> 文件在当前的 shell 立即生效，并且对于之后打开的 shell 都会有效。因此另一个等效的方法是退出并重新进入 shell，但这样也太麻烦了。</p><p>现在，你的 shell 就能自动寻找到 <code>/home/&lt;user name&gt;/bin/</code> 下的程序了，执行这个目录下的程序也不需要完整地写出程序的路径。</p><h3 id="自定义变量" tabindex="-1">自定义变量 <a class="header-anchor" href="#自定义变量" aria-label="Permalink to “自定义变量”">​</a></h3>',7)),l("p",null,[s[14]||(s[14]=e("当然，你也可以定义自己的变量。刚才我们看到的变量名称都是全大写的，实际上",-1)),a(i,{href:"https://bash.cyberciti.biz/guide/Rules_for_Naming_variable_name"},{default:t(()=>[...s[13]||(s[13]=[e("变量名称的定义还是比较灵活的",-1)])]),_:1}),s[15]||(s[15]=e("。",-1))]),s[33]||(s[33]=o(`<p>定义新变量的过程非常直观，直接对它赋值就可以了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>new_variable=&quot;Hello&quot;</span></span></code></pre></div><p>然后可以用以下的方式读取到已定义变量的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $new_variable</span></span></code></pre></div><p>程序的正常工作离不开各种变量，例如要将某个选项设置为打开，又或者让程序找到所需的代码库，都需要使用变量。在 bash 中运行程序的时候会生成一个子 shell，这个子 shell 和执行原程序的父 shell 并不是完全一样的，只是继承了父 shell 的部分内容，而且默认是不继承父 shell 中的变量的。因为变量默认情况下是局部变量，出于安全原因，一个 shell 中的局部变量不会被另一个 shell 读取到，即使是子 shell 也不可以。</p><p>下面举一个例子。首先定义一个变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>robots=&quot;R2D2 &amp; C3PO&quot;</span></span></code></pre></div><p>然后执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash</span></span></code></pre></div><p>现在是在 bash shell 中创建了一个子 shell。</p><p>执行这个命令看看还能不能读取到刚才定义的变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $robots</span></span></code></pre></div><p>你会发现读取不到。</p><p>还是在这个子 shell 中，为 <code>robots</code> 变量赋一个不同的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>robots=&quot;These aren&#39;t the ones you are looking for&quot;</span></span></code></pre></div><p>再读取一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $robots</span></span>
<span class="line"><span>These aren&#39;t the ones you are looking for</span></span></code></pre></div><p>退出这个子 shell：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exit</span></span></code></pre></div><p>然后再看一下现在 <code>robots</code> 变量的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $robots</span></span>
<span class="line"><span>R2D2 &amp; C3P0</span></span></code></pre></div><p>这一个特性可以有效避免配置过程中产生混乱，同时也会导致一个问题：如果程序中需要设置变量，但却由于子 shell 的原因无法正常访问到这个变量，该如何解决呢？这个时候就需要用到 <code>export</code> 了。</p><p>重复一次刚才的过程，但这一次不是通过 <code>robots=&quot;R2D2 &amp; C3PO&quot;</code> 方式来设置变量，而是使用 <code>export</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export robots=&quot;R2D2 &amp; C3PO&quot;</span></span></code></pre></div><p>现在你会发现，在进入子 shell 之后，<code>robots</code> 变量的值仍然是最初赋予的值。</p><p>要注意的是，尽管子 shell 会继承通过 <code>export</code> 导出的变量，但如果在子 shell 中对这个变量重新赋值，是不会影响到父 shell 中对应变量的。</p><p>如果要查看所有通过 <code>export</code> 导出的变量，可以执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export -p</span></span></code></pre></div><p>自定义的变量会显示在这个列表的末尾。这个列表中还有一些常见的变量：例如 <code>USER</code> 的值是当前用户的用户名，<code>PWD</code> 的值是当前用户当前所在的目录，而 <code>OLDPWD</code> 的值则是当前用户上一个访问过的目录。因此如果执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd -</span></span></code></pre></div><p>就会切换到上一个访问过的目录，那是因为 <code>cd</code> 命令读取到了 <code>OLDPWD</code> 变量的值。</p><p>你也可以使用 <code>env</code> 命令查看所有环境变量。</p><p>如果要取消导出一个变量，可以加上 <code>-n</code> 参数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export -n robots</span></span></code></pre></div><h3 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to “接下来”">​</a></h3><p>了解过环境变量的知识之后，你已经到达了可能对自己和他人造成危险的水平，接下来就需要了解如何通过使用别名来让环境变得更安全、更友好以保护自己了。</p><hr>`,37)),l("p",null,[s[17]||(s[17]=e("via: ",-1)),a(i,{href:"https://www.linux.com/blog/learn/2018/12/bash-variables-environmental-and-otherwise"},{default:t(()=>[...s[16]||(s[16]=[e("https://www.linux.com/blog/learn/2018/12/bash-variables-environmental-and-otherwise",-1)])]),_:1})]),l("p",null,[s[22]||(s[22]=e("作者：",-1)),a(i,{href:"https://www.linux.com/users/bro66"},{default:t(()=>[...s[18]||(s[18]=[e("Paul Brown",-1)])]),_:1}),s[23]||(s[23]=e(" 选题：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[19]||(s[19]=[e("lujun9972",-1)])]),_:1}),s[24]||(s[24]=e(" 译者：",-1)),a(i,{href:"https://github.com/HankChow"},{default:t(()=>[...s[20]||(s[20]=[e("HankChow",-1)])]),_:1}),s[25]||(s[25]=e(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[21]||(s[21]=[e("wxy",-1)])]),_:1})]),l("p",null,[s[28]||(s[28]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[26]||(s[26]=[e("LCTT",-1)])]),_:1}),s[29]||(s[29]=e(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...s[27]||(s[27]=[e("Linux中国",-1)])]),_:1}),s[30]||(s[30]=e(" 荣誉推出",-1))])])}const v=n(r,[["render",g]]);export{C as __pageData,v as default};
